<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\CostAccounting\Domain\Enums\CostPeriodStatus;use App\Modules\CostAccounting\Domain\Models\CostPeriod;use App\Modules\Orders\Domain\Enums\ProductionDemandStatus;use App\Modules\Orders\Domain\Models\ProductionDemand;use App\Modules\People\Domain\Models\Person;use App\Modules\Production\Domain\Enums\LaborMethod;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class ProductionDemandController extends Controller {public function __invoke(Request $request):Response{abort_unless($request->user()->hasPermission('orders.view'),403);$demands=ProductionDemand::query()->with(['orderLine.order.customer:id,name','orderLine.presentation.item:id,name','recipeVersion.recipe:id,name'])->where('status',ProductionDemandStatus::Pending)->get();$groups=$demands->groupBy('recipe_version_id')->map(function($items){$first=$items->first();return ['recipe_version_id'=>$first->recipe_version_id,'recipe'=>"{$first->recipeVersion->recipe->name} · v{$first->recipeVersion->version_number}",'pending_quantity'=>$items->sum(fn($d)=>(float)$d->pending_quantity),'dough_quantity'=>$items->sum(fn($d)=>(float)$d->pending_dough_quantity),'suggested_flour'=>$items->sum(fn($d)=>(float)$d->suggested_flour_quantity),'demands'=>$items->map(fn($d)=>['id'=>$d->id,'order'=>$d->orderLine->order->document_number,'customer'=>$d->orderLine->order->customer->name,'due_at'=>$d->orderLine->order->due_at->format('Y-m-d H:i'),'product'=>"{$d->orderLine->presentation->item->name} — {$d->orderLine->presentation->name}",'quantity'=>$d->pending_quantity,'dough'=>$d->pending_dough_quantity,'flour'=>$d->suggested_flour_quantity])];})->values();return Inertia::render('orders/Demand',['groups'=>$groups,'people'=>Person::query()->where('is_active',true)->orderBy('name')->get(['id','name']),'laborMethods'=>collect(LaborMethod::cases())->map(fn($m)=>['value'=>$m->value,'label'=>$m->label()]),'periods'=>CostPeriod::query()->where('status',CostPeriodStatus::Open)->get(['id','year','month','standard_labor_rate_per_kg']),'now'=>now()->format('Y-m-d\TH:i'),'canPlan'=>$request->user()->hasPermission('production.manage')]);}}
